public class AmortizedAnalysisDemo {
    // Demonstrating capacity expansion growth rate in a custom ArrayList-like structure
    private int[] elements = new int[10];
    private int size = 0;

    public void add(int element) {
        if (size == elements.length) {
            // Amortized O(1) resize operation: doubling capacity
            int[] nextArray = new int[elements.length * 2];
            System.arraycopy(elements, 0, nextArray, 0, elements.length);
            elements = nextArray;
        }
        elements[size++] = element;
    }
}
